-- PARKED, DO NOT RUN YET. Funder scholarships for study in other countries (Germany DAAD, Ireland, China, Hungary, Turkey, Japan, India, Korea and more). Owner wants these hidden until the app supports those countries. Official pages, checked 14 Nov 2026.
insert into scholarships (name, funder, country, funding_type, level, criteria, deadline, link, source_url, award_note, school_id, verified, demo)
select v.name, v.funder, v.country, v.funding_type, v.level, v.criteria, v.deadline, v.link, v.link, v.award_note, null, false, false
from (values
($q$Chinese Government Scholarship for Ghanaian Students (Masters and PhD)$q$,$q$China Scholarship Council with Ghana Scholarships Authority$q$,$q$China$q$,$q$Not stated$q$,$q$Postgraduate$q$,$q$Ghanaian citizens living in Ghana with at least a Second Class Upper degree. PhD applicants also need a relevant Master's. Age limit is 35 for Master's and 40 for PhD. Must be medically fit.$q$,NULL::date,$q$https://scholarships.gov.gh/opportunities/chinese-government-scholarship-awards-to-ghanaian-students-for-20262027-academic-year$q$,$q$Coverage not stated on the notice$q$),
($q$Hungarian Government Scholarships (Stipendium Hungaricum) for Ghanaians$q$,$q$Government of Hungary with Ghana Scholarships Authority$q$,$q$Hungary$q$,$q$Not stated$q$,$q$Undergraduate and postgraduate$q$,$q$Ghanaian citizens living in Ghana. Master's and PhD applicants need a Second Class Upper or better, 2 years of work experience, and completed national service. Age limit is 35 for Master's and 45 for PhD. Undergraduates need a WASSCE aggregate of 6 to 15 and be 23 or younger.$q$,NULL::date,$q$https://scholarships.gov.gh/opportunities/offer-of-scholarships-by-the-government-of-hungary-under-the-educational-exchange-programme-tenable-in-hungary$q$,$q$Coverage not stated on the notice$q$),
($q$Mauritius-Africa Scholarship Scheme$q$,$q$Government of Mauritius with Ghana Scholarships Authority$q$,$q$Mauritius$q$,$q$Not stated$q$,$q$Undergraduate and postgraduate$q$,$q$Ghanaian citizens living in Ghana, for full-time study at a public higher education institution in Mauritius (diploma, degree, Master's, MPhil, PhD). Undergraduates must be 18 to 25 on 1 January 2027, MPhil and PhD applicants under 40. Postgraduates send a short research plan.$q$,NULL::date,$q$https://scholarships.gov.gh/opportunities/the-mauritius-africa-scholarship-scheme-20262027-academic-year$q$,$q$Tuition, stipend and flights set by scheme terms, not itemised on the notice$q$),
($q$Joint Algeria/Ghana Government Scholarship Awards$q$,$q$Government of Algeria with Ghana Scholarships Authority$q$,$q$Algeria$q$,$q$Not stated$q$,$q$Undergraduate and postgraduate$q$,$q$Ghanaian citizens living in Ghana. Master's is a 2-year Master's in Islamic Studies and needs a Bachelor's in a related field. Other places need a WASSCE aggregate of 13 or better and age 23 or younger. Winners first do one year of French.$q$,NULL::date,$q$https://scholarships.gov.gh/opportunities/the-joint-algeriaghana-government-scholarship-awards-for-the-20262027-academic-year-tenable-in-algeria$q$,$q$Coverage not stated on the notice$q$),
($q$World in Serbia Scholarship$q$,$q$Government of Serbia with Ghana Scholarships Authority$q$,$q$Serbia$q$,$q$Not stated$q$,$q$Undergraduate and postgraduate$q$,$q$Ghanaian citizens who meet the academic needs of their chosen programme at an accredited public institution in Serbia, and who are nominated through the national selection process. Health and document rules apply.$q$,NULL::date,$q$https://scholarships.gov.gh/opportunities/scholarship-opportunity-in-the-republic-of-serbia$q$,$q$Coverage not stated on the notice$q$),
($q$Thailand International Postgraduate Programme (TIPP)$q$,$q$Thailand International Cooperation Agency (TICA) with Ghana Scholarships Authority$q$,$q$Thailand$q$,$q$Full$q$,$q$Postgraduate$q$,$q$For Ghanaian public sector workers in fields linked to the course. Needs nomination by your employing government agency and good health. The notice describes TIPP as full Master's degree scholarships.$q$,NULL::date,$q$https://scholarships.gov.gh/opportunities/scholarship-opportunities-and-thai-funded-training-programmes-20262027$q$,$q$Full Master's scholarship$q$),
($q$Scholarships in the Kingdom of Saudi Arabia (via Ghana Scholarships Authority)$q$,$q$Government of Saudi Arabia with Ghana Scholarships Authority$q$,$q$Saudi Arabia$q$,$q$Not stated$q$,$q$Undergraduate and postgraduate$q$,$q$Opportunities for Ghanaians at Saudi universities, announced by the Ghana Scholarships Authority. Apply only through the official portal at apply.scholarships.gov.gh. Check the notice for level and coverage.$q$,NULL::date,$q$https://scholarships.gov.gh/opportunities/scholarship-oppurtunities-in-the-kingdom-of-saudi-arabia$q$,$q$Coverage not stated on the official listing$q$),
($q$Ireland Fellows Programme (Masters)$q$,$q$Irish Aid, Government of Ireland$q$,$q$Ireland$q$,$q$Full$q$,$q$Postgraduate$q$,$q$Ghana is an eligible country. Needs a Bachelor's with GPA 3.0 of 4.0 or second class honours, awarded in 2015 or later, plus at least 3 years of relevant work experience. One-year Master's in Ireland. Shortlisted Ghanaians take the Duolingo English Test.$q$,NULL::date,$q$https://assets.ireland.ie/documents/IrelandFellows_AfricaGuidanceNote.pdf$q$,$q$Academic fees, economy flights, insurance, visa fees, monthly living stipend$q$),
($q$GETFund Foreign Postgraduate Scholarship$q$,$q$Ghana Education Trust Fund (GETFund)$q$,$q$Various$q$,$q$Not stated$q$,$q$Postgraduate$q$,$q$GETFund supports Masters and PhD scholars, including study abroad, for Ghanaians. The fund covers tuition, accommodation and scholastic materials. Eligibility and deadlines are on the GETFund scholarship portal.$q$,NULL::date,$q$https://www.getfund.gov.gh/service/scholarship-programme/$q$,$q$Tuition, accommodation and scholastic materials$q$),
($q$DAAD Study Scholarships for STEM Disciplines for Ghanaians$q$,$q$DAAD (German Academic Exchange Service)$q$,$q$Germany$q$,$q$Not stated$q$,$q$Postgraduate$q$,$q$For high-achieving students from developing and emerging countries with a first degree recognised in Germany. Covers a full-time on-campus Master's in maths, computer science, natural sciences or engineering at a German state or state-recognised university. People who already hold a Master's cannot apply.$q$,NULL::date,$q$https://www.daad-ghana.org/en/find-funding/masters-degree/$q$,$q$Master's study in Germany; amounts not stated on the page$q$),
($q$DAAD Development-Related Postgraduate Courses (EPOS)$q$,$q$DAAD (German Academic Exchange Service)$q$,$q$Germany$q$,$q$Not stated$q$,$q$Postgraduate$q$,$q$For graduates with at least a Second Class Upper degree, at least two years of relevant work experience, and a degree earned within the last six years. 12 to 24 month Master's courses for professionals focused on developing countries. Apply directly to the host university.$q$,NULL::date,$q$https://www.daad-ghana.org/en/find-funding/masters-degree/$q$,$q$Scholarship for Master's course in Germany; amounts not stated on the page$q$),
